  "command": "cat >> outline.json << 'EOF'\n    \"turning_point\": \"陆照野和谢长寂发现天道碑文可以被篡改，意识到所谓的天命可能是人为操控。这个发现让他们从被动接受命运转向主动反抗，同时多重外界压力逼近——玄冥调查、江浸月威胁、谢长渊行动——第二幕的危机正式开启。\"\n  },\n  \"act_two\": {\n    \"description\": \"冲突全面升级，两人调查天道碑真相，身份暴露，被正魔两道围剿，在逃亡中确认彼此心意\",\n    \"story_synopsis\": \"陆照野和谢长寂深入调查天道碑的起源，发现千年前的一场阴谋——天道碑并非天道所立，而是上古大能为控制修真界所造。他们寻找修改碑文的方法，却在这个过程中触发了玄冥的警觉。江浸月证实谢长寂魔宗身份并公之于众，谢长寂被迫离开天剑宗。陆照野在众人面前选择站在谢长寂这边，被宗主陆天行囚禁。谢长寂劫狱救出陆照野，两人正式成为修真界的叛徒。逃亡途中，他们遭遇正魔两道的联手追杀，谢长渊也在其中。在最绝望的时刻，两人在山洞中确认了彼此的心意。沈清辞为掩护他们而牺牲，临终前将修改天道碑的关键线索交给他们。第二幕在两人被迫跳入堕神渊逃避追杀时结束——那是连天道都无法触及的禁地。\",\n    \"key_chapters\": [\n      {\n        \"chapter_number\": 9,\n        \"chapter_title\": \"真相\",\n        \"chapter_synopsis\": \"陆照野和谢长寂在剑灵苍溟的指引下，来到一处上古遗迹。在那里他们发现了天道碑的起源——千年前一位上古大能为了控制修真界，创造了天道碑和应劫之子的谎言。真正的天道从未要求献祭，一切都是人为的骗局。这个发现让两人震惊，但也给了他们反抗的底气。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"上古遗迹入口，荒无人烟的废墟，被阵法封印\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\", \"剑灵苍溟\"],\n            \"scene_purpose\": \"揭开天道碑起源真相\",\n            \"core_action\": \"苍溟以自身灵力打开封印，三人进入遗迹深处\",\n            \"conflict_point\": \"苍溟警告说进去后就没有回头路\",\n            \"emotional_shift\": \"从犹豫 → 决心面对真相\",\n            \"scene_outcome\": \"进入遗迹，开始探索\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"遗迹核心，壁画和石碑记载了千年前的大战\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\"],\n            \"scene_purpose\": \"揭示天道碑骗局\",\n            \"core_action\": \"两人解读碑文，发现应劫之子只是控制修真界的工具\",\n            \"conflict_point\": \"陆照野颤抖着说\\\"我们都是被骗的祭品\\\"，谢长寂握住他的手\",\n            \"emotional_shift\": \"从震惊 → 愤怒 → 找到共同目标的坚定\",\n            \"scene_outcome\": \"两人决心要揭穿这个千年骗局\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"遗迹出口，夕阳西下，两人并肩而立\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\"],\n            \"scene_purpose\": \"两人关系深化，共同目标确立\",\n            \"core_action\": \"谢长寂说\\\"不管前路如何，我会一直陪着你\\\"，陆照野第一次主动回握他的手\",\n            \"conflict_point\": \"陆照野轻声说\\\"我不想再一个人了\\\"\",\n            \"emotional_shift\": \"从愤怒 → 被陪伴的温暖 → 心意相通\",\n            \"scene_outcome\": \"两人正式成为命运共同体，不只是契约，更是心意\"\n          }\n        ],\n        \"emotional_tone\": \"真相揭露的震撼与找到同伴的温暖\"\n      },\n      {\n        \"chapter_number\": 10,\n        \"chapter_title\": \"暴露\",\n        \"chapter_synopsis\": \"江浸月找到确凿证据证明谢长寂是魔宗卧底，在宗门大会上当众揭发。谢长寂身份暴露，被天剑宗弟子围攻。玄冥使者要求陆照野亲手处置谢长寂以证道心。陆照野在众人面前拔剑，却将剑尖指向玄冥，宣布谢长寂是他的人，谁也不能动。全场哗然，陆天行震怒。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"天剑宗大殿，宗门大会，各长老弟子齐聚\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\", \"江浸月\", \"玄冥使者\", \"宗主陆天行\", \"众长老\"],\n            \"scene_purpose\": \"谢长寂身份暴露，危机爆发\",\n            \"core_action\": \"江浸月出示证据，揭穿谢长寂魔宗身份，众人大惊\",\n            \"conflict_point\": \"谢长寂看向陆照野，眼中满是不舍和歉意\",\n            \"emotional_shift\": \"从平静的宗门日常 → 身份暴露的震惊\",\n            \"scene_outcome\": \"谢长寂被围攻，陷入绝境\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"大殿中央，陆照野挡在谢长寂身前\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\", \"玄冥使者\", \"宗主陆天行\"],\n            \"scene_purpose\": \"陆照野公开护短，立场坚定\",\n            \"core_action\": \"玄冥命令陆照野处置谢长寂，陆照野却拔剑指向玄冥\",\n            \"conflict_point\": \"陆照野说\\\"他是我的人，谁也别想动\\\"，全场哗然\",\n            \"emotional_shift\": \"从犹豫 → 坚定的守护\",\n            \"scene_outcome\": \"陆照野与宗门决裂，两人成为众矢之的\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"天剑宗地牢，陆照野被囚禁，谢长寂不知所踪\",\n            \"characters_present\": [\"陆照野\", \"宗主陆天行\"],\n            \"scene_purpose\": \"展示陆照野的决心\",\n            \"core_action\": \"陆天行质问陆照野为何护着魔道，陆照野说\\\"因为我信他\\\"\",\n            \"conflict_point\": \"陆天行说\\\"你会后悔的\\\"，陆照野冷笑说\\\"我已经后悔修无情道了\\\"\",\n            \"emotional_shift\": \"从被囚禁的愤怒 → 无悔的坚定\",\n            \"scene_outcome\": \"陆照野等待机会，相信谢长寂会来救他\"\n          }\n        ],\n        \"emotional_tone\": \"危机爆发的紧张与护短的坚定\"\n      },\n      {\n        \"chapter_number\": 11,\n        \"chapter_title\": \"劫狱\",\n        \"chapter_synopsis\": \"谢长寂潜入天剑宗地牢救出陆照野。两人在逃亡中遭遇重重围堵，谢长寂为保护陆照野受了重伤。陆照野背着重伤的谢长寂杀出重围，第一次真正释放自己的实力。他们逃到天剑宗外围的迷雾森林，暂时甩开追兵。谢长寂昏迷前对陆照野说\\\"师兄，我好像真的喜欢上你了\\\"。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"天剑宗地牢，深夜，谢长寂潜入\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\", \"守卫弟子\"],\n            \"scene_purpose\": \"谢长寂劫狱，救出陆照野\",\n            \"core_action\": \"谢长寂击败守卫，打开牢门，陆照野看到他时眼中闪过惊喜\",\n            \"conflict_point\": \"警报响起，追兵正在赶来\",\n            \"emotional_shift\": \"从等待的焦虑 → 重逢的喜悦\",\n            \"scene_outcome\": \"两人开始逃亡\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"天剑宗外围，重重围堵，剑光闪烁\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\", \"天剑宗追兵\"],\n            \"scene_purpose\": \"逃亡中的危机，谢长寂受伤\",\n            \"core_action\": \"谢长寂为挡下致命一击，后背被剑气贯穿，鲜血狂喷\",\n            \"conflict_point\": \"陆照野接住倒下的谢长寂，眼中第一次露出恐慌\",\n            \"emotional_shift\": \"从逃亡的紧张 → 看到爱人受伤的恐惧\",\n            \"scene_outcome\": \"谢长寂重伤，陆照野背着他继续逃\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"迷雾森林深处，谢长寂靠在树下，脸色苍白\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\"],\n            \"scene_purpose\": \"谢长寂表白，感情线突破\",\n            \"core_action\": \"谢长寂昏迷前轻声说\\\"师兄，我好像真的喜欢上你了\\\"，陆照野愣住，然后紧紧抱住他\",\n            \"conflict_point\": \"陆照野哽咽着说\\\"你不许死，我还没有告诉你我也喜欢你\\\"\",\n            \"emotional_shift\": \"从恐惧失去 → 确认心意的悲痛\",\n            \"scene_outcome\": \"两人心意相通，谢长寂昏迷\"\n          }\n        ],\n        \"emotional_tone\": \"生死逃亡中的深情告白\"\n      },\n      {\n        \"chapter_number\": 12,\n        \"chapter_title\": \"疗伤\",\n        \"chapter_synopsis\": \"陆照野在迷雾森林中寻找草药为谢长寂疗伤。他第一次体会到害怕失去的感觉，明白了修无情道只是在逃避。谢长寂昏迷中反复叫着陆照野的名字，陆照野守在他身边寸步不离。沈清辞长老暗中送来丹药和地图，告诉他们躲避追兵的方法，并表示会继续调查天道碑的线索。\",\n        \"scene_sequence\": [\n          {\n            \"scene_number\": 1,\n            \"scene_location\": \"迷雾森林深处，临时搭建的草棚，谢长寂昏迷不醒\",\n            \"characters_present\": [\"陆照野\", \"谢长寂\"],\n            \"scene_purpose\": \"陆照野的内心转变，体会情感\",\n            \"core_action\": \"陆照野用布巾擦拭谢长寂额头的冷汗，手微微发抖\",\n            \"conflict_point\": \"他意识到如果谢长寂死了，自己修无情道还有什么意义\",\n            \"emotional_shift\": \"从冷静自持 → 害怕失去的脆弱\",\n            \"scene_outcome\": \"陆照野决心放下无情道，直面自己的感情\"\n          },\n          {\n            \"scene_number\": 2,\n            \"scene_location\": \"森林深处，陆照野采药，危险四伏\",\n            \"characters_present\": [\"陆照野\", \"毒兽\"],\n            \"scene_purpose\": \"展示陆照野的决心\",\n            \"core_action\": \"陆照野为采一株灵草，与守护毒兽搏斗，身上添了数道伤口\",\n            \"conflict_point\": \"他不顾自身安危，只想尽快回去救谢长寂\",\n            \"emotional_shift\": \"从为修炼而战斗 → 为救爱人而战斗\",\n            \"scene_outcome\": \"采到灵草，赶回草棚\"\n          },\n          {\n            \"scene_number\": 3,\n            \"scene_location\": \"草棚，沈清辞暗中来访\",\n            \"characters_present\": [\"陆照野\", \"沈清辞\"],\n            \"scene_purpose\": \"沈清辞提供帮助，埋下后续线索\",\n            \"core_action\": \"沈清辞送来丹药和地图，告诉陆照野有一处安全之地可暂避\",\n            \"conflict_point\": \"沈清辞说\\\"我会继续调查，你们一定要活下去\\\"\",\n            \"emotional_shift\": \"从孤立无援 → 得到支援的希望\",\n            \"scene_outcome\": \"陆照野感激沈清辞，决定带谢长寂前往安全之地\"\n          }\n        ],\n        \"emotional_tone\": \"守护与希望的温暖\"\n      }\nEOF\n"
